import sys, json, os
ROOT = sys.argv[1]
_s = open(ROOT + '/gen/style.py').read()
exec(_s[:_s.index('# ---- BOARD ----')])                      # palette, ICONS, line_icon, wrap
_l = open(ROOT + '/gen/lineup.py').read()
cx = {'__name__': 'x', 'sys': sys}
exec(_l[:_l.index('GROUND = 470')], cx)
pbody, phead, pbaby, small, CLIP = cx['x']['body'], cx['x']['head'], cx['baby'], cx['x']['small'], cx['A']['clip']
P = ROOT + '/project/'
FIELD, CARD, MUTED, LINE = '#EAE2D2', '#ECE4D4', '#6B5E52', '#E0D6C3'
SYS = "font-family: -apple-system, system-ui, 'Helvetica Neue', sans-serif"
DSP = "font-family: 'Bricolage Grotesque', system-ui, sans-serif"

# ---------------- little UI kit (390 x 844 screens) ----------------
def ico(name, size=26): return f'<svg aria-hidden="true" width="{size}" height="{size}" viewBox="0 0 24 24">{line_icon(name)}</svg>'
def face(size=44, col=SKY, e='happy', baby_=False):
    inner = pbaby(e, A) if baby_ else phead(e) + CLIP(160, 56, '#E5553B')
    vb = '30 30 180 180' if baby_ else '34 30 176 170'
    return f'<div style="width: {size}px; height: {size}px; border-radius: 50%; background: {col}; overflow: hidden; flex: none; display: flex; align-items: center; justify-content: center"><svg aria-hidden="true" width="{size*0.86:.0f}" height="{size*0.86:.0f}" viewBox="{vb}">{inner}</svg></div>'
def puggle(h=150, arms='wave', e='happy', col=HARB): return f'<svg aria-hidden="true" width="{h*0.8:.0f}" height="{h}" viewBox="0 0 240 300">{pbody(arms, e, col) + CLIP(160, 56, "#E5553B")}</svg>'
def hdr(sub, title, right=''): return f'<div style="display: flex; align-items: flex-end; justify-content: space-between; margin: 6px 0 4px"><div><div style="font-size: 14px; color: {MUTED}">{sub}</div><div style="{DSP}; font-size: 31px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.1">{title}</div></div>{right}</div>'
def nav(title, left='Back', right=''): return f'<div style="display: flex; align-items: center; justify-content: space-between; height: 44px"><div style="font-size: 16px; color: {HARB}; width: 80px">{("‹ " + left) if left else ""}</div><div style="font-size: 17px; font-weight: 700">{title}</div><div style="font-size: 16px; color: {HARB}; width: 80px; text-align: right; font-weight: 600">{right}</div></div>'
def chip(t, c=SKY, on=True): return f'<span style="display: inline-flex; align-items: center; height: 26px; padding: 0 11px; border-radius: 99px; background: {c if on else "transparent"}; border: 1.5px solid {c if on else LINE}; font-size: 13px; font-weight: 700; color: {INK if on else MUTED}">{t}</span>'
def chips(items): return '<div style="display: flex; gap: 8px; flex-wrap: wrap">' + ''.join(chip(*i) if isinstance(i, tuple) else chip(i) for i in items) + '</div>'
def seg(items, active=0): return f'<div style="display: flex; background: {FIELD}; border-radius: 14px; padding: 4px">' + ''.join(f'<div style="flex: 1; text-align: center; padding: 9px 0; border-radius: 11px; font-size: 15px; font-weight: 700; background: {PAPER if i == active else "transparent"}; color: {INK if i == active else MUTED}">{t}</div>' for i, t in enumerate(items)) + '</div>'
def btn(t, kind='primary'):
    bg, fg, bd = {'primary': (INK, PAPER, INK), 'ghost': (PAPER, INK, LINE), 'yellow': (A, INK, A), 'danger': (PAPER, WAR, LINE), 'quiet': ('transparent', MUTED, 'transparent')}[kind]
    return f'<div style="height: 54px; border-radius: 27px; background: {bg}; color: {fg}; border: 1.5px solid {bd}; display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700">{t}</div>'
def field(label, value, hint=''): return f'<div style="background: {FIELD}; border-radius: 16px; padding: 12px 16px; display: flex; justify-content: space-between; align-items: center"><div><div style="font-size: 16px; font-weight: 600">{label}</div>{f"<div style=|font-size: 12px; color: {MUTED}|>{hint}</div>".replace("|", chr(34)) if hint else ""}</div><div style="font-size: 16px; color: {MUTED}">{value}</div></div>'
def toggle(label, on=True, sub=''):
    sw = f'<div style="width: 50px; height: 30px; border-radius: 15px; background: {GUM if on else LINE}; position: relative; flex: none"><div style="position: absolute; top: 3px; left: {23 if on else 3}px; width: 24px; height: 24px; border-radius: 50%; background: {PAPER}"></div></div>'
    return f'<div style="background: {FIELD}; border-radius: 16px; padding: 12px 16px; display: flex; justify-content: space-between; align-items: center; gap: 12px"><div><div style="font-size: 16px; font-weight: 600">{label}</div>{f"<div style=|font-size: 12px; color: {MUTED}|>{sub}</div>".replace("|", chr(34)) if sub else ""}</div>{sw}</div>'
def big(v, unit): return f'<div style="display: flex; align-items: center; justify-content: space-between; padding: 4px 8px"><div style="width: 52px; height: 52px; border-radius: 50%; background: {FIELD}; display: flex; align-items: center; justify-content: center; font-size: 28px">−</div><div style="{DSP}; font-size: 68px; font-weight: 800; letter-spacing: -0.03em">{v}<span style="font-size: 20px; font-weight: 600; color: {MUTED}; {SYS}"> {unit}</span></div><div style="width: 52px; height: 52px; border-radius: 50%; background: {FIELD}; display: flex; align-items: center; justify-content: center; font-size: 28px">+</div></div>'
def crow(name, age, status, col, button='Asleep', baby_=False, e='happy'): return f'<div style="display: flex; align-items: center; gap: 12px; background: {PAPER}; border-radius: 22px; padding: 12px">{face(50, col, e, baby_)}<div style="flex: 1"><div style="font-size: 17px; font-weight: 700">{name} <span style="font-weight: 400; color: {MUTED}">{age}</span></div><div style="font-size: 14px; color: {MUTED}">{status}</div></div>{f"<div style=|height: 38px; padding: 0 14px; border-radius: 19px; background: {FIELD}; display: flex; align-items: center; font-size: 14px; font-weight: 700|>{button}</div>".replace("|", chr(34)) if button else ""}</div>'
def card(icon, title, lines, plus=True): return f'<div style="background: {CARD}; border-radius: 24px; padding: 13px; display: flex; flex-direction: column; gap: 6px"><div style="display: flex; justify-content: space-between">{ico(icon, 28)}{f"<div style=|width: 36px; height: 36px; border-radius: 50%; background: {PAPER}; display: flex; align-items: center; justify-content: center; font-size: 22px|>+</div>".replace("|", chr(34)) if plus else ""}</div><div style="font-size: 18px; font-weight: 700">{title}</div>' + ''.join(f'<div style="font-size: 13px; color: {MUTED}">{l}</div>' for l in lines) + '</div>'
def grid(*cards): return '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px">' + ''.join(cards) + '</div>'
def row(icon, title, sub, right='', who=None): return f'<div style="display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid {LINE}"><div style="width: 38px; height: 38px; border-radius: 50%; background: {FIELD}; display: flex; align-items: center; justify-content: center; flex: none">{ico(icon, 22) if icon in ICONS else f"<span style=|font-size: 17px|>{icon}</span>".replace("|", chr(34))}</div><div style="flex: 1"><div style="font-size: 16px; font-weight: 600">{title}</div><div style="font-size: 13px; color: {MUTED}; display: flex; gap: 6px; align-items: center">{chip(*who) if who else ""}{sub}</div></div><div style="font-size: 14px; color: {MUTED}">{right}</div></div>'
def lst(*rows): return f'<div style="background: {PAPER}; border-radius: 22px; padding: 2px 14px">' + ''.join(rows).replace(f'border-top: 1px solid {LINE}', 'border-top: 0', 1) + '</div>'
def p(t, size=15, col=MUTED, w=400, center=False): return f'<div style="font-size: {size}px; color: {col}; font-weight: {w}; line-height: 1.35{"; text-align: center" if center else ""}">{t}</div>'
def h(t, size=28, center=False): return f'<div style="{DSP}; font-size: {size}px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.12{"; text-align: center" if center else ""}">{t}</div>'
def banner(t, c=SUN, strong=''): return f'<div style="background: {c}; border-radius: 16px; padding: 11px 14px; font-size: 14px; line-height: 1.3"><b>{strong}</b> {t}</div>'
def toast(t): return f'<div style="position: absolute; left: 16px; right: 16px; bottom: 102px; background: {INK}; color: {PAPER}; border-radius: 16px; padding: 13px 16px; font-size: 15px; display: flex; justify-content: space-between"><span>{t}</span><span style="font-weight: 700; color: {A}">Undo</span></div>'
def sp(n=10): return f'<div style="height: {n}px; flex: none"></div>'
def fill(): return '<div style="flex: 1"></div>'
def center(*kids): return '<div style="display: flex; flex-direction: column; align-items: center; gap: 12px">' + ''.join(kids) + '</div>'
def sticker(name, n=44): return f'<svg aria-hidden="true" width="{n}" height="{n}" viewBox="0 0 24 24">{sticker_icon(name, "f" + str(abs(hash((name, n))) % 9999) + str(_uid()))}</svg>'
_n = [0]
def _uid():
    _n[0] += 1; return _n[0]
TABS = ['Today', 'History', 'Insights', 'Family']
def tabbar(active): return f'<div style="position: absolute; left: 0; right: 0; bottom: 0; height: 84px; background: {PAPER}; border-top: 1px solid {LINE}; display: flex; padding-top: 12px">' + ''.join(f'<div style="flex: 1; text-align: center; font-size: 12px; font-weight: {800 if t == active else 500}; color: {INK if t == active else MUTED}"><div style="width: 26px; height: 5px; border-radius: 3px; background: {INK if t == active else "transparent"}; margin: 0 auto 8px"></div>{t}</div>' for t in TABS) + '</div>'
def sheet(title, *kids, h_=None): return (f'<div style="position: absolute; inset: 0; background: rgba(58,42,32,0.38)"></div><div style="position: absolute; left: 0; right: 0; bottom: 0; {f"height: {h_}px; " if h_ else ""}background: {PAPER}; border-radius: 34px 34px 0 0; padding: 10px 18px 30px; display: flex; flex-direction: column; gap: 12px; box-sizing: border-box">'
                                          f'<div style="width: 40px; height: 5px; border-radius: 3px; background: {LINE}; margin: 0 auto 2px"></div><div style="display: flex; justify-content: space-between; align-items: center"><div style="font-size: 20px; font-weight: 800">{title}</div><div style="width: 32px; height: 32px; border-radius: 50%; background: {FIELD}; display: flex; align-items: center; justify-content: center; font-size: 16px">✕</div></div>' + ''.join(kids) + '</div>')
def S(*kids, tab='Today', over='', bg=SAND, fg=INK, pad=16):
    status = f'<div style="height: 50px; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 30px 6px; font-size: 16px; font-weight: 700; flex: none"><span>9:41</span><span style="font-size: 12px">●●● ▮</span></div>'
    return (f'<div style="width: 390px; height: 844px; background: {bg}; color: {fg}; {SYS}; position: relative; overflow: hidden; display: flex; flex-direction: column">{status}'
            f'<div style="flex: 1; display: flex; flex-direction: column; gap: 10px; padding: 0 {pad}px {96 if tab else 28}px; overflow: hidden">{"".join(kids)}</div>{tabbar(tab) if tab else ""}{over}</div>')

OL, BE = ('Ollie', SKY), ('Bea', SHELL)
today_rows = crow('Ollie', '2½', 'Awake since 6:50 am', SKY) + crow('Bea', '6 mo', 'Bottle 150 ml, 40 min ago', SHELL, baby_=True)
today_cards = grid(card('Bottle', 'Bottle', ['Bea · 9:00 am']), card('Sleep', 'Sleep', ['Bea · woke 8:10 am']), card('Nappy', 'Nappy', ['Bea · 8:30 am']), card('Potty', 'Potty', ['Ollie · 2 today']), card('Solids', 'Solids', ['Bea · 7:30 am']), card('Milestone', 'Milestone', ['Add a first']))
TODAY = S(hdr('Tuesday 10 November', 'Ollie and Bea'), today_rows, today_cards)

# ---------------- the flows ----------------
FLOWS = []
def flow(fid, title, intro, steps, edges): FLOWS.append(dict(id=fid, title=title, intro=intro, steps=steps, edges=edges))

