def chartrow(days, got):
    return '<div style="display: flex; gap: 4px">' + ''.join(f'<div style="flex: 1; background: {SAND}; border-radius: 12px; padding: 6px 0; min-height: 150px; display: flex; flex-direction: column; align-items: center; gap: 2px"><div style="font-size: 12px; font-weight: 800">{d}</div>' + ''.join(sticker(n, 38) for n in g) + '</div>' for d, g in zip(days, got)) + '</div>'
