# ---------------- render ----------------
SC = 0.6
def mini(html, label): return f'<div role="img" aria-label="{label}" style="width: {390*SC:.0f}px; height: {844*SC:.0f}px; border-radius: 26px; overflow: hidden; flex: none; box-shadow: 0 0 0 1.5px {LINE}"><div style="transform: scale({SC}); transform-origin: top left">{html}</div></div>'
T = 'font-size: 13px; font-weight: 500; color: #4A3B30; line-height: 1.4'
H = 'font-size: 13px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #5A4636'
def board(fl):
    cells = ''.join(f'<div style="display: flex; flex-direction: column; gap: 6px; width: {390*SC:.0f}px">{mini(html, fl["title"] + ": " + t)}<div style="font-size: 15px; font-weight: 800">{i+1}. {t}</div><div style="{T}; font-size: 12px">{n}</div></div>' for i, (t, n, html) in enumerate(fl['steps']))
    edges = ''.join(f'<li style="{T}">{e_}</li>' for e_ in fl['edges'])
    rows = (len(fl['steps']) + 3) // 4
    height = 150 + rows * (844*SC + 96) + 40 + 24 * len(fl['edges'])
    body = (f'<div style="width: 1080px; height: {height:.0f}px; box-sizing: border-box; background: {SAND}; color: #2A1F18; {DSP}; padding: 40px 48px; display: flex; flex-direction: column; gap: 18px">'
            f'<div style="display: flex; flex-direction: column; gap: 6px"><h1 style="margin: 0; font-size: 34px; font-weight: 800; letter-spacing: -0.02em">{fl["title"]}</h1><div style="{T}; font-size: 15px">{fl["intro"]}</div></div>'
            f'<div style="display: flex; flex-wrap: wrap; gap: 22px 16px">{cells}</div><div><div style="{H}">Rules and edge cases</div><ul style="margin: 6px 0 0; padding-left: 18px">{edges}</ul></div></div>')
    return body, round(height)
def node(t, sub, c): return f'<div style="background: {c}; border-radius: 16px; padding: 10px 14px; min-width: 150px"><div style="font-size: 15px; font-weight: 800">{t}</div><div style="{T}; font-size: 12px">{sub}</div></div>'
def lane(title, items, c): return f'<div style="display: flex; align-items: center; gap: 12px"><div style="width: 128px; font-size: 14px; font-weight: 800">{title}</div><div style="display: flex; gap: 10px; flex-wrap: wrap; flex: 1">{"".join(node(t, s_, c) for t, s_ in items)}</div></div>'
MAP = [('First time', [('Splash', 'name shows here'), ('Hello', '2 screens, skippable'), ('Add a child', 'the only required step'), ('Character', 'friend or photo'), ('Invite', 'optional')], SUN),
       ('Today (tab)', [('Children', 'status, sleep button'), ('Activity cards', '+ opens a sheet'), ('Log sheets', 'bottle, nappy, potty…'), ('Sticker moment', 'after a potty success'), ('Milestone', 'the big celebration')], PAPER),
       ('History (tab)', [('Timeline', 'by day'), ('Filter', 'who and what'), ('Edit entry', 'change or delete')], PAPER),
       ('Insights (tab)', [('Last night', 'per child'), ('Trends', 'weekly'), ('Summary', 'PDF to share')], PAPER),
       ('Family (tab)', [('Children', 'pages, characters'), ('People', 'invite, roles'), ('Settings', 'night, units, reminders'), ('Pro and tips', 'free core'), ('Help and about', 'name shows here')], PAPER),
       ('Outside the app', [('Lock Screen', 'sleep and feed timers'), ('Widgets', 'last feed, asleep for'), ('Notifications', 'only ones you switch on'), ('Invite link', 'opens Join')], MINT)]
map_body = (f'<div style="width: 1080px; height: 760px; box-sizing: border-box; background: {SAND}; color: #2A1F18; {DSP}; padding: 40px 48px; display: flex; flex-direction: column; gap: 16px">'
            f'<div style="display: flex; flex-direction: column; gap: 6px"><h1 style="margin: 0; font-size: 36px; font-weight: 800; letter-spacing: -0.02em">App map and journeys</h1><div style="{T}; font-size: 15px; max-width: 940px">Four tabs, with everything else a sheet over Today. Ten journeys follow on this page, each as numbered screens with its rules and edge cases. Screens are wireframes: layout and words, not final polish.</div></div>'
            + ''.join(lane(*l_) for l_ in MAP)
            + f'<div style="display: flex; gap: 10px; flex-wrap: wrap; margin-top: 6px">{"".join(chip(f["title"], PAPER) for f in FLOWS)}</div></div>')

if __name__ == '__main__':
    c = json.load(open(P + 'canvas.json')); keep = json.dumps(c)
    made = [('FlowMap.dc.html', 'App map and journeys', map_body, 760)]
    for fl in FLOWS:
        b_, h_ = board(fl); made.append((f'Flow_{fl["id"]}.dc.html', 'Journey ' + fl['title'], b_, h_))
    y = 0; entries = {}
    for fn, title, b_, h_ in made:
        wrap(title, b_, 1080, h_, fn, 0); entries[fn] = dict(x=0, y=y, w=1080, h=h_, title=title, page='flows'); y += h_ + 160
    c = json.loads(keep)
    if not any(pg['id'] == 'flows' for pg in c['pages']): c['pages'].insert(1, {'id': 'flows', 'name': 'Flows'})
    for fn, e_ in entries.items():
        c['boards'][fn] = e_
        if fn not in c['order']: c['order'].append(fn)
    json.dump(c, open(P + 'canvas.json', 'w'), separators=(',', ':'))
    # the same flows as a document for the repo
    md = ['# Puggle: flows and journeys', '', 'Generated from `design/canvas/gen/flows.py`; the canvas page "Flows" shows each step as a screen. Change the script, not this file.', '']
    md += ['## App map', '']
    for title, items, _ in MAP: md.append(f'- **{title}:** ' + '; '.join(f'{t} ({s_})' for t, s_ in items))
    for fl in FLOWS:
        md += ['', f'## {fl["title"]}', '', fl['intro'], '']
        md += [f'{i+1}. **{t}.** {n}' for i, (t, n, _) in enumerate(fl['steps'])]
        md += ['', 'Rules and edge cases:', ''] + [f'- {e_}' for e_ in fl['edges']]
    os.makedirs(ROOT + '/out', exist_ok=True); open(ROOT + '/out/flows.md', 'w').write('\n'.join(md) + '\n')
    print(len(made), 'boards;', sum(len(f['steps']) for f in FLOWS), 'screens')
